async connect() {
  let openAuthorizedSocket;
  if (this.dshaPrepareLanMux) {
    const pending = new AbortController();
    this.cancelCandidate = () => pending.abort();
    const deadline = setTimeout(() => pending.abort(), 10000);
    try {
      openAuthorizedSocket = await this.dshaPrepareLanMux(pending.signal);
      if (pending.signal.aborted) throw new Error("LAN WebSocket authorization interrupted");
    } finally {
      clearTimeout(deadline);
      this.cancelCandidate = undefined;
    }
  }
  const socket = openAuthorizedSocket ? openAuthorizedSocket() : this.openSocket(REMOTE_STREAM_MUX_PATH);
